# Genera una transcripción visual: columna izquierda arriba-abajo, luego derecha.
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path -Parent $PSScriptRoot;$ppt=(Get-ChildItem (Join-Path $root 'Bilbioteca\3. Talleres PIS') -Filter 'EDITABLE*.pptx'|Select-Object -First 1).FullName;$out=Join-Path $root 'tmp\manual_pis_visual.txt';New-Item -ItemType Directory -Force (Split-Path $out)|Out-Null
$z=[IO.Compression.ZipFile]::OpenRead($ppt);$all=@();for($n=1;$n -le 51;$n++){$e=$z.GetEntry("ppt/slides/slide$n.xml");$r=[IO.StreamReader]::new($e.Open());$s=$r.ReadToEnd();$r.Close();$sh=@();foreach($m in [regex]::Matches($s,'<p:sp>(.*?)</p:sp>',[Text.RegularExpressions.RegexOptions]::Singleline)){$v=$m.Groups[1].Value;$o=[regex]::Match($v,'<a:off x="(\d+)" y="(\d+)"');$t=(([regex]::Matches($v,'<a:t>(.*?)</a:t>',[Text.RegularExpressions.RegexOptions]::Singleline)|%{$_.Groups[1].Value})-join "`n").Trim();if($o.Success -and $t){$sh+=[pscustomobject]@{x=[int]$o.Groups[1].Value;y=[int]$o.Groups[2].Value;t=$t}}};$all+="`n--- DIAPOSITIVA $n ---";$all+=($sh|Sort-Object @{e={if($_.x -lt 4000000){0}else{1}}},y|%{$_.t})};$z.Dispose();Set-Content -LiteralPath $out -Value $all -Encoding utf8;Write-Output $out
